# Dart/Flutter Log Patterns

Copy-paste-ready logging patterns for Flutter/Dart debugging.

## Basic Debug Output

```dart
// Simple value logging
debugPrint('[ClassName] methodName: variable=$variable');

// Multiple values
debugPrint('[ClassName] methodName: a=$a, b=$b, c=$c');

// Conditional/state logging
debugPrint('[ClassName] condition check: isValid=$isValid, value=$value');

// Method entry/exit
debugPrint('[ClassName] methodName: ENTER params=($param1, $param2)');
debugPrint('[ClassName] methodName: EXIT result=$result');
```

## Widget Lifecycle

```dart
@override
void initState() {
  super.initState();
  debugPrint('[${widget.runtimeType}] initState');
}

@override
void didChangeDependencies() {
  super.didChangeDependencies();
  debugPrint('[${widget.runtimeType}] didChangeDependencies');
}

@override
void didUpdateWidget(covariant OldWidget oldWidget) {
  super.didUpdateWidget(oldWidget);
  debugPrint('[${widget.runtimeType}] didUpdateWidget');
}

@override
void dispose() {
  debugPrint('[${widget.runtimeType}] dispose');
  super.dispose();
}
```

## Build Tracking

```dart
@override
Widget build(BuildContext context) {
  debugPrint('[${widget.runtimeType}] build: key=${widget.key}');
  return Container(
    // ...
  );
}

// With state info
@override
Widget build(BuildContext context) {
  debugPrint('[${widget.runtimeType}] build: isLoading=$isLoading, itemCount=${items.length}');
  return // ...
}
```

## Async Operations

```dart
Future<void> fetchData() async {
  debugPrint('[ClassName] fetchData: START');
  try {
    final result = await api.getData();
    debugPrint('[ClassName] fetchData: SUCCESS count=${result.length}');
  } catch (e, stackTrace) {
    debugPrint('[ClassName] fetchData: ERROR $e');
    debugPrint('[ClassName] fetchData: STACK $stackTrace');
  }
}
```

## Stream Handling

```dart
stream.listen(
  (data) {
    debugPrint('[ClassName] stream: DATA received=$data');
  },
  onError: (error) {
    debugPrint('[ClassName] stream: ERROR $error');
  },
  onDone: () {
    debugPrint('[ClassName] stream: DONE');
  },
);
```

## State Management

### setState

```dart
void updateCounter() {
  debugPrint('[ClassName] updateCounter: BEFORE counter=$counter');
  setState(() {
    counter++;
  });
  debugPrint('[ClassName] updateCounter: AFTER counter=$counter');
}
```

### Provider/Riverpod

```dart
// Provider notifyListeners
void updateState(String newValue) {
  debugPrint('[ClassName] updateState: from=$_value to=$newValue');
  _value = newValue;
  notifyListeners();
}

// Riverpod state change
ref.listen<MyState>(myProvider, (previous, next) {
  debugPrint('[ClassName] state changed: $previous -> $next');
});
```

### BLoC

```dart
// Event handling
on<MyEvent>((event, emit) {
  debugPrint('[MyBloc] event received: $event');
  debugPrint('[MyBloc] current state: $state');
  emit(newState);
  debugPrint('[MyBloc] new state: $newState');
});
```

## Gesture Handling

```dart
GestureDetector(
  onTap: () {
    debugPrint('[MyWidget] onTap triggered');
    // ... handler code
  },
  onTapDown: (details) {
    debugPrint('[MyWidget] onTapDown: position=${details.globalPosition}');
  },
  onPanStart: (details) {
    debugPrint('[MyWidget] onPanStart: position=${details.globalPosition}');
  },
  onPanUpdate: (details) {
    debugPrint('[MyWidget] onPanUpdate: delta=${details.delta}');
  },
  onPanEnd: (details) {
    debugPrint('[MyWidget] onPanEnd: velocity=${details.velocity}');
  },
)
```

## Navigation

```dart
// Push
debugPrint('[ClassName] navigating to: /details');
Navigator.pushNamed(context, '/details', arguments: {'id': id});

// Pop
debugPrint('[ClassName] popping with result: $result');
Navigator.pop(context, result);

// Route observer
class DebugRouteObserver extends RouteObserver<PageRoute<dynamic>> {
  @override
  void didPush(Route<dynamic> route, Route<dynamic>? previousRoute) {
    debugPrint('[Router] PUSH: ${previousRoute?.settings.name} -> ${route.settings.name}');
    super.didPush(route, previousRoute);
  }

  @override
  void didPop(Route<dynamic> route, Route<dynamic>? previousRoute) {
    debugPrint('[Router] POP: ${route.settings.name} -> ${previousRoute?.settings.name}');
    super.didPop(route, previousRoute);
  }
}
```

## API Calls

```dart
Future<Response> makeApiCall(String endpoint, Map<String, dynamic> body) async {
  debugPrint('[ApiClient] REQUEST: $endpoint');
  debugPrint('[ApiClient] BODY: ${jsonEncode(body)}');

  final response = await http.post(Uri.parse(endpoint), body: body);

  debugPrint('[ApiClient] RESPONSE: status=${response.statusCode}');
  debugPrint('[ApiClient] RESPONSE BODY: ${response.body}');

  return response;
}
```

## Conditional Branches

```dart
void processItem(Item item) {
  if (item.isValid) {
    debugPrint('[ClassName] processItem: branch=VALID item=${item.id}');
    // valid path
  } else if (item.isPending) {
    debugPrint('[ClassName] processItem: branch=PENDING item=${item.id}');
    // pending path
  } else {
    debugPrint('[ClassName] processItem: branch=INVALID item=${item.id}');
    // invalid path
  }
}
```

## Loop Iterations

```dart
for (var i = 0; i < items.length; i++) {
  debugPrint('[ClassName] processing: iteration=${i + 1}/${items.length} item=${items[i].id}');
  // process item
}

// For each with index
items.asMap().forEach((index, item) {
  debugPrint('[ClassName] forEach: ${index + 1}/${items.length} item=${item.id}');
});
```

## Performance Timing

```dart
final stopwatch = Stopwatch()..start();
// ... operation
stopwatch.stop();
debugPrint('[ClassName] operation took: ${stopwatch.elapsedMilliseconds}ms');
```

## Notes

- `debugPrint` is throttled and safe for large output (unlike `print`)
- Use `kDebugMode` check to conditionally include logging:
  ```dart
  if (kDebugMode) {
    debugPrint('[ClassName] debug info');
  }
  ```
- For production logging, consider using `logger` package

# JavaScript/TypeScript Log Patterns

Copy-paste-ready logging patterns for JavaScript/TypeScript debugging.

## Basic Console Logging

```javascript
// Simple value logging
console.log('[ClassName] methodName:', variable);

// Multiple values (object shorthand)
console.log('[ClassName] methodName:', { a, b, c });

// Conditional logging
console.log('[ClassName] condition check:', { isValid, value });

// Method entry/exit
console.log('[ClassName] methodName: ENTER', { param1, param2 });
console.log('[ClassName] methodName: EXIT', { result });

// With string interpolation
console.log(`[ClassName] methodName: variable=${variable}`);
```

## Console Log Levels

```javascript
console.log('General information');     // Standard log
console.info('Informational message');  // Info level
console.warn('Warning message');        // Warning level
console.error('Error message');         // Error level
console.debug('Debug details');         // Debug level (may be hidden by default)
```

## Grouped Logging

```javascript
console.group('[ClassName] methodName');
console.log('input:', params);
console.log('processing...');
console.log('output:', result);
console.groupEnd();

// Collapsed by default
console.groupCollapsed('[ClassName] details');
console.log('detailed info 1');
console.log('detailed info 2');
console.groupEnd();
```

## Async Operations

```javascript
async function fetchData() {
  console.log('[ClassName] fetchData: START');
  try {
    const result = await api.getData();
    console.log('[ClassName] fetchData: SUCCESS', { count: result.length });
    return result;
  } catch (error) {
    console.error('[ClassName] fetchData: ERROR', error);
    throw error;
  }
}

// Promise chain
fetchData()
  .then(result => {
    console.log('[ClassName] then: received', { result });
  })
  .catch(error => {
    console.error('[ClassName] catch: error', { error });
  })
  .finally(() => {
    console.log('[ClassName] finally: cleanup');
  });
```

## React Component Lifecycle

```javascript
// Functional component with hooks
function MyComponent({ prop }) {
  console.log('[MyComponent] render:', { prop });

  useEffect(() => {
    console.log('[MyComponent] mounted');
    return () => {
      console.log('[MyComponent] unmounted');
    };
  }, []);

  useEffect(() => {
    console.log('[MyComponent] prop changed:', { prop });
  }, [prop]);

  return <div>...</div>;
}

// Class component
class MyComponent extends React.Component {
  componentDidMount() {
    console.log('[MyComponent] componentDidMount');
  }

  componentDidUpdate(prevProps, prevState) {
    console.log('[MyComponent] componentDidUpdate:', {
      prevProps,
      currentProps: this.props,
      prevState,
      currentState: this.state,
    });
  }

  componentWillUnmount() {
    console.log('[MyComponent] componentWillUnmount');
  }

  render() {
    console.log('[MyComponent] render');
    return <div>...</div>;
  }
}
```

## State Management

### useState

```javascript
const [state, setState] = useState(initialValue);

const updateState = (newValue) => {
  console.log('[Component] updateState: from=', state, 'to=', newValue);
  setState(newValue);
};
```

### useReducer

```javascript
const loggerReducer = (reducer) => (state, action) => {
  console.group(`[Reducer] ${action.type}`);
  console.log('Previous State:', state);
  console.log('Action:', action);
  const nextState = reducer(state, action);
  console.log('Next State:', nextState);
  console.groupEnd();
  return nextState;
};

const [state, dispatch] = useReducer(loggerReducer(reducer), initialState);
```

### Redux

```javascript
// Middleware logger
const loggerMiddleware = (store) => (next) => (action) => {
  console.group(`[Redux] ${action.type}`);
  console.log('dispatching:', action);
  console.log('prev state:', store.getState());
  const result = next(action);
  console.log('next state:', store.getState());
  console.groupEnd();
  return result;
};
```

### Zustand

```javascript
const useStore = create((set, get) => ({
  value: 0,
  setValue: (newValue) => {
    console.log('[Store] setValue:', { from: get().value, to: newValue });
    set({ value: newValue });
  },
}));
```

## Event Handlers

```javascript
// Click handler
const handleClick = (event) => {
  console.log('[Component] click:', {
    target: event.target,
    position: { x: event.clientX, y: event.clientY },
  });
};

// Form submit
const handleSubmit = (event) => {
  event.preventDefault();
  const formData = new FormData(event.target);
  console.log('[Form] submit:', Object.fromEntries(formData));
};

// Input change
const handleChange = (event) => {
  console.log('[Input] change:', {
    name: event.target.name,
    value: event.target.value,
  });
};
```

## API Requests (fetch)

```javascript
async function apiCall(url, options = {}) {
  console.log('[API] REQUEST:', { url, options });

  const response = await fetch(url, options);
  const data = await response.json();

  console.log('[API] RESPONSE:', {
    status: response.status,
    ok: response.ok,
    data,
  });

  return data;
}
```

## API Requests (Axios)

```javascript
// Interceptors
axios.interceptors.request.use((config) => {
  console.log('[Axios] REQUEST:', {
    method: config.method,
    url: config.url,
    data: config.data,
  });
  return config;
});

axios.interceptors.response.use(
  (response) => {
    console.log('[Axios] RESPONSE:', {
      status: response.status,
      data: response.data,
    });
    return response;
  },
  (error) => {
    console.error('[Axios] ERROR:', {
      status: error.response?.status,
      data: error.response?.data,
    });
    return Promise.reject(error);
  }
);
```

## Router (React Router)

```javascript
// Custom hook for route logging
function useRouteLogger() {
  const location = useLocation();

  useEffect(() => {
    console.log('[Router] navigation:', {
      pathname: location.pathname,
      search: location.search,
      state: location.state,
    });
  }, [location]);
}

// Navigation
const navigate = useNavigate();
const goToDetail = (id) => {
  console.log('[Component] navigating to:', `/detail/${id}`);
  navigate(`/detail/${id}`);
};
```

## LocalStorage/SessionStorage

```javascript
const storage = {
  set(key, value) {
    console.log('[Storage] set:', { key, value });
    localStorage.setItem(key, JSON.stringify(value));
  },
  get(key) {
    const value = JSON.parse(localStorage.getItem(key));
    console.log('[Storage] get:', { key, value });
    return value;
  },
  remove(key) {
    console.log('[Storage] remove:', { key });
    localStorage.removeItem(key);
  },
};
```

## Conditional Branches

```javascript
function processItem(item) {
  if (item.isValid) {
    console.log('[ClassName] processItem: branch=VALID', { itemId: item.id });
    // valid path
  } else if (item.isPending) {
    console.log('[ClassName] processItem: branch=PENDING', { itemId: item.id });
    // pending path
  } else {
    console.log('[ClassName] processItem: branch=INVALID', { itemId: item.id });
    // invalid path
  }
}

// Switch statement
switch (status) {
  case 'loading':
    console.log('[ClassName] status: branch=LOADING');
    break;
  case 'success':
    console.log('[ClassName] status: branch=SUCCESS');
    break;
  case 'error':
    console.log('[ClassName] status: branch=ERROR');
    break;
  default:
    console.log('[ClassName] status: branch=UNKNOWN', { status });
}
```

## Loop Iterations

```javascript
items.forEach((item, index) => {
  console.log(`[ClassName] processing: ${index + 1}/${items.length}`, { item });
});

// For...of with index
for (const [index, item] of items.entries()) {
  console.log(`[ClassName] iteration: ${index + 1}/${items.length}`, { item });
}

// Array methods
